-- Чек-лист запуска школы: заголовок со словом «идеальную» под запросы не бьёт.
UPDATE t_p78828167_tutor_platform_1.feed_articles
SET title = 'Как запустить онлайн-школу с нуля: чек-лист из 8 пунктов',
    summary = 'Из чего состоит онлайн-школа, которая доводит учеников до конца: программа, уроки, проверка знаний, оплата с чеками и удержание. Практический чек-лист для тех, кто запускает обучение и не хочет нанимать IT-команду.',
    content = content || E'\n\n---\n\n## Сколько это стоит на старте\n\nСамый частый вопрос после такого чек-листа — во сколько обойдётся собрать всё перечисленное.\n\nКлассический путь: методист пишет программу (от 30 тысяч за курс), разработчик собирает кабинет и подключает эквайринг, дизайнер делает бренд. Плюс абонплата платформы — она списывается каждый месяц независимо от того, продали вы хоть что-то.\n\nАбонплата — это налог на надежду. Площадка получает деньги, даже если у вас ноль продаж, и потому не заинтересована в вашей выручке.\n\nМы сознательно сделали иначе: **конструктор курсов бесплатный, абонплаты нет, платформа берёт 8% с продажи.** Нет продаж — вы ничего не должны.\n\nПрограмму по этому чек-листу ИИ соберёт за минуту: модули, уроки с конспектами, задания, квизы, рекомендованную цену и тексты для объявления. [Попробуйте на своей теме](/school-builder) — без карты и регистрации, PDF останется у вас. Условия и комиссия — [на странице для репетиторов](/repetitoram).',
    updated_at = now()
WHERE slug = 'kak-sozdat-idealnuyu-onlayn-shkolu';

-- Анализ рынка: заголовок длинный, обрезается в выдаче; описание без запроса.
UPDATE t_p78828167_tutor_platform_1.feed_articles
SET title = 'Рынок онлайн-школ 2026: кто лидирует и куда идёт спрос',
    summary = 'Как устроен рынок онлайн-образования в 2026 году, какие школы держат рейтинги, почему реклама дорожает быстрее выручки и что даёт небольшой школе шанс против крупных игроков.',
    content = content || E'\n\n---\n\n## Что из этого следует для небольшой школы\n\nВывод про ИИ звучит абстрактно, пока не перевести его в расходы.\n\nКрупный игрок встраивает ИИ силами своей команды разработки. У школы из двух преподавателей такой команды нет — и раньше это означало, что конкурировать нечем, кроме цены.\n\nСейчас инфраструктура сдаётся в аренду. Конструктор собирает программу курса за минуту, ИИ-наставник отвечает вашим ученикам круглосуточно строго в рамках вашей программы, приём оплат с чеками по 54-ФЗ и выдача доступов уже встроены. Свой бренд, свой домен — платформа в кадре не появляется.\n\nБез абонплаты: 8% с продажи. Это и есть вся разница в стартовых вложениях.\n\n[Соберите программу своего курса бесплатно](/school-builder) — без регистрации. Демо для школы и учебного центра — [на странице для бизнеса](/for-business#lead).',
    updated_at = now()
WHERE slug = 'analiz-rynka-onlayn-shkol-2026';

-- Методология: самая дочитываемая статья раздела, но вела только на мини-курсы.
UPDATE t_p78828167_tutor_platform_1.feed_articles
SET content = content || E'\n\n---\n\n## Если вы делаете курсы сами\n\nВсё описанное выше — это работа методиста. Она честно стоит недель: разбить тему на модули, каждый модуль на уроки, к каждому уроку придумать проверку, которую нельзя пройти не поняв.\n\nБольшинство экспертов останавливается именно здесь. Не потому что не знают предмет, а потому что между знанием и курсом стоит стена методической работы, за которую никто не платит.\n\nМы отдали эту часть машине. Вы называете тему и число уроков — ИИ возвращает программу по модулям, уроки с типом занятия и конспектом, практическое задание к каждому и квиз с отмеченным верным ответом. Плюс заголовки, посты, цепочку писем и рекомендованную цену.\n\nЭто рабочий черновик, а не готовый продукт: мясо на каркас нарастает только из вашего опыта — живых примеров и разбора типичных ошибок. Но разница между «исправить» и «создать с нуля» и есть вся экономия.\n\n[Проверьте на своей теме](/school-builder) — бесплатно, без карты и регистрации.',
    updated_at = now()
WHERE slug = 'kak-my-delaem-kursy-metodologiya-uchispro';
